PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "accounts_user" ("password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "is_staff" bool NOT NULL, "date_joined" datetime NOT NULL, "id" char(32) NOT NULL PRIMARY KEY, "email" varchar(254) NOT NULL UNIQUE, "phone" varchar(17) NOT NULL, "role" varchar(20) NOT NULL, "profile_image" varchar(100) NULL, "is_active" bool NOT NULL, "is_online" bool NOT NULL, "last_activity" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "accounts_loginattempt" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "username" varchar(255) NOT NULL, "ip_address" char(39) NOT NULL, "attempt_count" integer NOT NULL, "last_attempt" datetime NOT NULL, "locked_until" datetime NULL);
CREATE TABLE IF NOT EXISTS "accounts_useractivitylog" ("id" char(32) NOT NULL PRIMARY KEY, "action" varchar(20) NOT NULL, "model_name" varchar(100) NOT NULL, "object_id" varchar(100) NOT NULL, "description" text NOT NULL, "ip_address" char(39) NULL, "user_agent" text NOT NULL, "created_at" datetime NOT NULL, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "account_emailconfirmation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created" datetime NOT NULL, "sent" datetime NULL, "key" varchar(64) NOT NULL UNIQUE, "email_address_id" integer NOT NULL REFERENCES "account_emailaddress" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "account_emailaddress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "verified" bool NOT NULL, "primary" bool NOT NULL, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "email" varchar(254) NOT NULL);
CREATE TABLE IF NOT EXISTS "accounts_userprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_birth" date NULL, "address" text NOT NULL, "emergency_contact" varchar(100) NOT NULL, "emergency_phone" varchar(17) NOT NULL, "hire_date" date NULL, "department" varchar(100) NOT NULL, "bio" text NOT NULL, "theme" varchar(10) NOT NULL, "notifications_enabled" bool NOT NULL, "user_id" char(32) NOT NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "employee_id" varchar(50) NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_company" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "legal_name" varchar(200) NOT NULL, "tax_id" varchar(50) NOT NULL, "registration_no" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "mobile" varchar(20) NOT NULL, "website" varchar(200) NOT NULL, "address" text NOT NULL, "city" varchar(100) NOT NULL, "state" varchar(100) NOT NULL, "postal_code" varchar(20) NOT NULL, "country" varchar(100) NOT NULL, "logo" varchar(100) NULL, "favicon" varchar(100) NULL, "currency" varchar(3) NOT NULL, "currency_symbol" varchar(5) NOT NULL, "date_format" varchar(20) NOT NULL, "time_format" varchar(20) NOT NULL, "timezone" varchar(50) NOT NULL, "enable_loyalty" bool NOT NULL, "enable_prescription" bool NOT NULL, "enable_multi_branch" bool NOT NULL, "enable_email_notifications" bool NOT NULL, "enable_sms_notifications" bool NOT NULL, "invoice_prefix" varchar(20) NOT NULL, "invoice_footer_text" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_emailtemplate" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(100) NOT NULL UNIQUE, "subject" varchar(200) NOT NULL, "body" text NOT NULL, "variables" text NOT NULL CHECK ((JSON_VALID("variables") OR "variables" IS NULL)), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_systemsetting" ("id" char(32) NOT NULL PRIMARY KEY, "setting_key" varchar(100) NOT NULL UNIQUE, "setting_value" text NOT NULL, "setting_type" varchar(20) NOT NULL, "description" text NOT NULL, "is_encrypted" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_activitylog" ("id" char(32) NOT NULL PRIMARY KEY, "action" varchar(20) NOT NULL, "model_name" varchar(100) NOT NULL, "object_id" varchar(100) NOT NULL, "object_repr" varchar(200) NOT NULL, "changes" text NOT NULL CHECK ((JSON_VALID("changes") OR "changes" IS NULL)), "ip_address" char(39) NULL, "user_agent" text NOT NULL, "url" varchar(500) NOT NULL, "method" varchar(10) NOT NULL, "created_at" datetime NOT NULL, "user_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_backup" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "backup_type" varchar(20) NOT NULL, "file_path" varchar(500) NOT NULL, "file_size" bigint NOT NULL, "status" varchar(20) NOT NULL, "started_at" datetime NOT NULL, "completed_at" datetime NULL, "error_message" text NOT NULL, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_branch" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(100) NOT NULL, "code" varchar(20) NOT NULL UNIQUE, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "address" text NOT NULL, "is_main_branch" bool NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "manager_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "company_id" char(32) NOT NULL REFERENCES "core_company" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_document" ("id" char(32) NOT NULL PRIMARY KEY, "document_type" varchar(20) NOT NULL, "document_number" varchar(100) NOT NULL, "file" varchar(100) NOT NULL, "related_model" varchar(100) NOT NULL, "related_id" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "size" integer NOT NULL, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_notification" ("id" char(32) NOT NULL PRIMARY KEY, "title" varchar(200) NOT NULL, "message" text NOT NULL, "notification_type" varchar(20) NOT NULL, "priority" varchar(10) NOT NULL, "is_read" bool NOT NULL, "read_at" datetime NULL, "link" varchar(500) NOT NULL, "created_at" datetime NOT NULL, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "inventory_category" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(100) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "description" text NOT NULL, "icon" varchar(50) NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "parent_id" char(32) NULL REFERENCES "inventory_category" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "inventory_inventoryadjustment" ("id" char(32) NOT NULL PRIMARY KEY, "adjustment_number" varchar(50) NOT NULL UNIQUE, "reason" varchar(20) NOT NULL, "quantity" integer NOT NULL, "previous_quantity" integer NOT NULL, "new_quantity" integer NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "approved_at" datetime NULL, "approved_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" char(32) NOT NULL REFERENCES "inventory_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "inventory_stockalert" ("id" char(32) NOT NULL PRIMARY KEY, "alert_type" varchar(20) NOT NULL, "message" text NOT NULL, "current_value" integer NOT NULL, "threshold_value" integer NOT NULL, "status" varchar(20) NOT NULL, "resolved_at" datetime NULL, "created_at" datetime NOT NULL, "product_id" char(32) NOT NULL REFERENCES "inventory_product" ("id") DEFERRABLE INITIALLY DEFERRED, "resolved_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "inventory_stockmovement" ("id" char(32) NOT NULL PRIMARY KEY, "movement_type" varchar(20) NOT NULL, "quantity" integer NOT NULL, "previous_quantity" integer NOT NULL, "new_quantity" integer NOT NULL, "unit_price" decimal NULL, "total_amount" decimal NULL, "reference_type" varchar(50) NOT NULL, "reference_id" varchar(100) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" char(32) NOT NULL REFERENCES "inventory_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "inventory_product" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "generic_name" varchar(200) NOT NULL, "sku" varchar(50) NOT NULL UNIQUE, "barcode" varchar(50) NULL UNIQUE, "product_type" varchar(20) NOT NULL, "pack_size" varchar(100) NOT NULL, "purchase_price" decimal NOT NULL, "selling_price" decimal NULL, "wholesale_price" decimal NULL, "discount_percent" decimal NOT NULL, "reorder_level" integer NOT NULL, "reorder_quantity" integer NOT NULL, "max_stock_level" integer NULL, "current_stock" integer NOT NULL, "minimum_stock" integer NOT NULL, "maximum_stock" integer NOT NULL, "unit" varchar(20) NOT NULL, "prescription_required" varchar(20) NOT NULL, "ingredients" text NOT NULL, "dosage" varchar(200) NOT NULL, "storage_conditions" varchar(200) NOT NULL, "image" varchar(100) NULL, "is_active" bool NOT NULL, "is_featured" bool NOT NULL, "is_prescription" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" char(32) NULL REFERENCES "inventory_category" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "description" text NOT NULL, "is_controlled" bool NOT NULL, "license_number" varchar(100) NOT NULL, "requires_license" bool NOT NULL, "side_effects" text NOT NULL, "vat_percent" decimal NOT NULL, "batch_number" varchar(100) NULL, "expiry_date" date NULL);
CREATE TABLE IF NOT EXISTS "sales_loyaltycard" ("id" char(32) NOT NULL PRIMARY KEY, "card_number" varchar(50) NOT NULL UNIQUE, "points_balance" integer NOT NULL, "points_earned" integer NOT NULL, "points_redeemed" integer NOT NULL, "is_active" bool NOT NULL, "issued_date" datetime NOT NULL, "expiry_date" datetime NULL, "customer_id" char(32) NOT NULL UNIQUE REFERENCES "sales_customer" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "sales_payment" ("id" char(32) NOT NULL PRIMARY KEY, "payment_number" varchar(50) NOT NULL UNIQUE, "amount" decimal NOT NULL, "payment_method" varchar(20) NOT NULL, "reference_number" varchar(100) NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "sale_id" char(32) NOT NULL REFERENCES "sales_sale" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "sales_loyaltytransaction" ("id" char(32) NOT NULL PRIMARY KEY, "transaction_type" varchar(20) NOT NULL, "points" integer NOT NULL, "balance_after" integer NOT NULL, "description" text NOT NULL, "created_at" datetime NOT NULL, "loyalty_card_id" char(32) NOT NULL REFERENCES "sales_loyaltycard" ("id") DEFERRABLE INITIALLY DEFERRED, "sale_id" char(32) NULL REFERENCES "sales_sale" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "sales_creditrecord" ("id" char(32) NOT NULL PRIMARY KEY, "credit_number" varchar(50) NOT NULL UNIQUE, "customer_name" varchar(200) NOT NULL, "credit_amount" decimal NOT NULL, "amount_paid" decimal NOT NULL, "remaining_balance" decimal NOT NULL, "due_date" date NULL, "status" varchar(20) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "customer_id" char(32) NULL REFERENCES "sales_customer" ("id") DEFERRABLE INITIALLY DEFERRED, "sale_id" char(32) NOT NULL REFERENCES "sales_sale" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "sales_saleitem" ("id" char(32) NOT NULL PRIMARY KEY, "quantity" integer NOT NULL, "unit_price" decimal NOT NULL, "discount_percent" decimal NOT NULL, "discount_amount" decimal NOT NULL, "tax_amount" decimal NOT NULL, "subtotal" decimal NOT NULL, "original_price" decimal NOT NULL, "prescription_required" bool NOT NULL, "prescription_verified" bool NOT NULL, "created_at" datetime NOT NULL, "product_id" char(32) NOT NULL REFERENCES "inventory_product" ("id") DEFERRABLE INITIALLY DEFERRED, "sale_id" char(32) NOT NULL REFERENCES "sales_sale" ("id") DEFERRABLE INITIALLY DEFERRED, "batch_number" varchar(100) NULL, "expiry_date" date NULL, "pack_size" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "sales_salereturn" ("id" char(32) NOT NULL PRIMARY KEY, "return_number" varchar(50) NOT NULL UNIQUE, "return_date" datetime NOT NULL, "reason" varchar(20) NOT NULL, "notes" text NOT NULL, "subtotal" decimal NOT NULL, "total_amount" decimal NOT NULL, "status" varchar(20) NOT NULL, "refund_processed" bool NOT NULL, "created_at" datetime NOT NULL, "approved_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "customer_id" char(32) NULL REFERENCES "sales_customer" ("id") DEFERRABLE INITIALLY DEFERRED, "sale_id" char(32) NOT NULL REFERENCES "sales_sale" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "sales_salereturnitem" ("id" char(32) NOT NULL PRIMARY KEY, "quantity" integer NOT NULL, "unit_price" decimal NOT NULL, "subtotal" decimal NOT NULL, "reason" text NOT NULL, "created_at" datetime NOT NULL, "product_id" char(32) NOT NULL REFERENCES "inventory_product" ("id") DEFERRABLE INITIALLY DEFERRED, "sale_item_id" char(32) NOT NULL REFERENCES "sales_saleitem" ("id") DEFERRABLE INITIALLY DEFERRED, "sale_return_id" char(32) NOT NULL REFERENCES "sales_salereturn" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "sales_customer" ("id" char(32) NOT NULL PRIMARY KEY, "customer_code" varchar(50) NOT NULL UNIQUE, "first_name" varchar(100) NOT NULL UNIQUE, "last_name" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "date_of_birth" date NULL, "address" text NOT NULL, "city" varchar(100) NOT NULL, "state" varchar(100) NOT NULL, "postal_code" varchar(20) NOT NULL, "customer_type" varchar(20) NOT NULL, "discount_percent" decimal NOT NULL, "credit_limit" decimal NOT NULL, "current_balance" decimal NOT NULL, "loyalty_points" integer NOT NULL, "total_spent" decimal NOT NULL, "notes" text NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "phone_number" varchar(20) NOT NULL UNIQUE, "phone_number_2" varchar(20) NOT NULL, "fin" varchar(50) NOT NULL UNIQUE, "tin" varchar(50) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "sales_sale" ("id" char(32) NOT NULL PRIMARY KEY, "invoice_number" varchar(50) NOT NULL UNIQUE, "customer_name" varchar(200) NOT NULL, "sale_date" datetime NOT NULL, "subtotal" decimal NOT NULL, "discount_amount" decimal NOT NULL, "discount_percent" decimal NOT NULL, "tax_amount" decimal NOT NULL, "total_amount" decimal NOT NULL, "amount_paid" decimal NOT NULL, "change_amount" decimal NOT NULL, "payment_status" varchar(20) NOT NULL, "credit_amount" decimal NOT NULL, "has_credit" bool NOT NULL, "status" varchar(20) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "customer_id" char(32) NULL REFERENCES "sales_customer" ("id") DEFERRABLE INITIALLY DEFERRED, "prescription_image" varchar(100) NULL, "prescription_number" varchar(100) NOT NULL, "prescription_required" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "socialaccount_socialapp" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "name" varchar(40) NOT NULL, "client_id" varchar(191) NOT NULL, "secret" varchar(191) NOT NULL, "key" varchar(191) NOT NULL, "provider_id" varchar(200) NOT NULL, "settings" text NOT NULL CHECK ((JSON_VALID("settings") OR "settings" IS NULL)));
CREATE TABLE IF NOT EXISTS "socialaccount_socialtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "token_secret" text NOT NULL, "expires_at" datetime NULL, "account_id" integer NOT NULL REFERENCES "socialaccount_socialaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "app_id" integer NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "socialaccount_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(200) NOT NULL, "uid" varchar(191) NOT NULL, "last_login" datetime NOT NULL, "date_joined" datetime NOT NULL, "user_id" char(32) NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "extra_data" text NOT NULL CHECK ((JSON_VALID("extra_data") OR "extra_data" IS NULL)));
CREATE TABLE IF NOT EXISTS "purchases_purchaseorder" ("id" char(32) NOT NULL PRIMARY KEY, "po_number" varchar(50) NOT NULL UNIQUE, "order_date" datetime NOT NULL, "notes" text NOT NULL, "subtotal" decimal NOT NULL, "total_amount" decimal NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" char(32) NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "invoice_number" varchar(100) NULL, "supplier_name" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "purchases_purchaseorderitem" ("id" char(32) NOT NULL PRIMARY KEY, "quantity" integer NOT NULL, "unit_price" decimal NOT NULL, "subtotal" decimal NOT NULL, "created_at" datetime NOT NULL, "product_id" char(32) NOT NULL REFERENCES "inventory_product" ("id") DEFERRABLE INITIALLY DEFERRED, "purchase_order_id" char(32) NOT NULL REFERENCES "purchases_purchaseorder" ("id") DEFERRABLE INITIALLY DEFERRED, "batch_number" varchar(100) NULL, "expiry_date" date NULL, "markup_percent" decimal NOT NULL, "selling_price" decimal NULL);
